import{_ as a,o,c as r,a2 as t}from"./chunks/framework.1C62pOns.js";const l=JSON.parse('{"title":"Documentação do Pro Agent Hub","description":"","frontmatter":{},"headers":[],"relativePath":"pt/index.md","filePath":"pt/index.md","lastUpdated":1787839708000}'),n={name:"pt/index.md"};function s(d,e,c,m,i,u){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="documentacao-do-pro-agent-hub" tabindex="-1">Documentação do Pro Agent Hub <a class="header-anchor" href="#documentacao-do-pro-agent-hub" aria-label="Permalink to &quot;Documentação do Pro Agent Hub&quot;">​</a></h1><p>O Pro Agent Hub é uma plataforma para criar e operar assistentes de IA: agentes, times, bases de conhecimento, serviços MCP, workflows e aplicações web — tudo configurado por tela, com Python onde a tela não alcança.</p><h2 id="por-onde-comecar" tabindex="-1">Por onde começar <a class="header-anchor" href="#por-onde-comecar" aria-label="Permalink to &quot;Por onde começar&quot;">​</a></h2><p><strong><a href="/pro-agent-hub-installer/pt/instalacao">Instalação</a></strong> — colocar a plataforma no ar, no Linux, Windows ou macOS.</p><p><strong><a href="/pro-agent-hub-installer/pt/funcoes/">Referência das funções</a></strong> — o que você pode chamar em cada tela de código. A plataforma tem <strong>sete lugares</strong> onde se escreve Python, e o que está disponível difere em cada um: quem aprende <code>db_query(...)</code> num Workflow e escreve o mesmo numa ferramenta de Agente recebe <code>NameError</code>. Essa seção diz exatamente o que existe onde.</p><h2 id="sobre-esta-documentacao" tabindex="-1">Sobre esta documentação <a class="header-anchor" href="#sobre-esta-documentacao" aria-label="Permalink to &quot;Sobre esta documentação&quot;">​</a></h2><p>A referência das funções é <strong>gerada a partir do código-fonte</strong> — dos mesmos construtores de escopo que a plataforma usa para executar. Uma operação nova aparece aqui sem ninguém precisar lembrar dela; uma removida some. Não há uma lista escrita à mão para envelhecer.</p><p>O manual das telas (com imagens) está em preparação.</p>',8)])])}const h=a(n,[["render",s]]);export{l as __pageData,h as default};
